حهٔ <?=fa_number($txPage)?> از <?=fa_number($txPages)?></span><?php if($txPage<$txPages): ?><a class="ghost" href="<?=h('index.php?'.http_build_query(array_merge($_GET,['tx_page'=>$txPage+1])))?>">صفحهٔ بعد</a><?php endif ?></nav><?php endif ?></section>
